.sales-chart-note{margin-top:5px;text-align:center;color:#8996a4;font-size:10px}
.sales-refined .sales-support{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px;align-items:stretch;margin-bottom:14px}
.sales-refined .sales-support>.sales-card{min-height:190px;padding:18px}
.sales-refined .sales-support .sales-card>header{margin-bottom:18px}
.sales-refined .sales-support .sales-card header p{font-size:10px;color:#8a97a4;margin:4px 0 0}
.sales-refined .sales-status-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 20px}
