.sales-status-dot{width:8px;height:8px;border-radius:50%;background:#159d8e;flex:0 0 8px}
.sales-status.status-blue .sales-status-dot{background:#5697d1}.sales-status.status-violet .sales-status-dot{background:#9076cc}.sales-status.status-green .sales-status-dot{background:#49a878}
.sales-refined .sales-status progress{height:5px;margin-top:8px}
.sales-refined .sales-status.status-blue progress::-webkit-progress-value{background:#5697d1}.sales-refined .sales-status.status-blue progress::-moz-progress-bar{background:#5697d1}
.sales-refined .sales-status.status-violet progress::-webkit-progress-value{background:#9076cc}.sales-refined .sales-status.status-violet progress::-moz-progress-bar{background:#9076cc}
