/* Sales visual polish */
.seller-sales{
    --sales-teal:#078f84;
    --sales-orange:#d9872c;
    --sales-navy:#1c2d43;
    --sales-muted:#7d8a9b;
    --sales-border:#e5eaf0;
    --sales-shadow:0 4px 14px rgba(27,46,68,.045);
    background:#f6f8fa;
    border:1px solid #edf0f4;
    border-radius:18px;
    padding:20px;
}
.seller-sales .sales-heading{align-items:center;gap:24px;margin-bottom:4px}
.seller-sales .sales-heading-copy{min-width:250px}
.seller-sales .sales-eyebrow{font-size:10px;font-weight:750;letter-spacing:.15em;color:var(--sales-teal);margin-bottom:5px}
.seller-sales .sales-heading h1{font-size:27px;line-height:1.2;letter-spacing:-.7px;color:var(--sales-navy);margin:0 0 7px}
.seller-sales .sales-welcome{font-size:12px;font-weight:700;color:var(--sales-teal);margin:0 0 3px}
.seller-sales .sales-heading-copy>p:last-child{font-size:12px;line-height:1.5;color:var(--sales-muted);margin:0}
.seller-sales .sales-heading .sales-filters{
    align-items:center;justify-content:flex-end;gap:8px;max-width:840px;
    padding:6px;background:#fff;border:1px solid var(--sales-border);border-radius:12px;
    box-shadow:0 2px 7px rgba(27,46,68,.035);
}
.seller-sales .sales-heading .sales-filters>label{min-width:0}
.seller-sales .sales-heading .sales-filters>label:first-of-type{min-width:150px}
.seller-sales .sales-heading .sales-filters .input{
    height:36px;min-height:36px;max-width:210px;padding:0 30px 0 11px;
    border:1px solid #e8edf2;border-radius:8px;background-color:#fff;
    color:var(--sales-navy);font-weight:650;box-shadow:none;
}
.seller-sales .sales-heading .sales-period{max-width:none;font-size:10px;line-height:1.3}
.seller-sales .sales-heading .sales-filters button,
.seller-sales .sales-heading .sales-export{
    display:inline-flex;align-items:center;justify-content:center;gap:7px;
    height:36px;min-height:36px;padding:0 13px;border-radius:8px;
    font-size:11px;font-weight:700;white-space:nowrap;transition:background-color .16s,border-color .16s,color .16s,box-shadow .16s,transform .16s;
}
.seller-sales .sales-heading .sales-filters button{background:var(--sales-teal);box-shadow:0 2px 5px rgba(7,143,132,.16)}
.seller-sales .sales-heading .sales-filters button:hover{background:#06796f;transform:translateY(-1px)}
.seller-sales .sales-heading .sales-export{border-color:#dfe6eb;color:#46576c;background:#fff}
.seller-sales .sales-heading .sales-export:hover{border-color:#b9dcd7;color:var(--sales-teal);background:#f5fbfa}
.seller-sales :is(button,a,input,select):focus-visible{outline:3px solid rgba(7,143,132,.2);outline-offset:2px}
.seller-sales .sales-tabs{gap:25px;margin:19px 0 16px;border-color:#dfe6eb}
.seller-sales .sales-tabs a{padding:0 2px 11px;font-size:12px;font-weight:700;transition:color .16s,border-color .16s}
.seller-sales .sales-tabs a:hover{color:var(--sales-teal)}
.seller-sales .sales-card{
    border:1px solid var(--sales-border);border-radius:14px;background:#fff;
    padding:18px;box-shadow:var(--sales-shadow);transition:box-shadow .18s,border-color .18s,transform .18s;
}
.seller-sales .sales-kpi:hover{border-color:#d6e8e5;box-shadow:0 8px 20px rgba(27,46,68,.075);transform:translateY(-2px)}
.seller-sales .sales-card>header{gap:14px;margin-bottom:15px}
.seller-sales .sales-card h2{color:var(--sales-navy);font-size:14px;font-weight:700;letter-spacing:-.1px}
.seller-sales .sales-card header p{color:var(--sales-muted);font-size:11px;line-height:1.45}
.seller-sales .sales-kpis{gap:14px;margin:0 0 16px}
.seller-sales .sales-kpi{min-height:133px;padding:17px 18px}
.seller-sales .sales-kpi>div{gap:10px}
.seller-sales .sales-kpi .sales-icon{width:34px;height:34px;border-radius:10px;background:#e9f7f4;color:var(--sales-teal)}
.seller-sales .sales-kpi .sales-icon svg{width:17px;height:17px}
.seller-sales .sales-kpi:nth-child(4) .sales-icon{background:#fff2e5;color:var(--sales-orange)}
.seller-sales .sales-kpi h2{font-size:12px;font-weight:650;color:#647388}
.seller-sales .sales-kpi>strong{margin:13px 0 5px;font-size:clamp(22px,1.8vw,27px);line-height:1.1;letter-spacing:-.8px;color:var(--sales-navy)}
.seller-sales .sales-kpi p{font-size:10px;color:#8b97a6}
.seller-sales .sales-analytics{grid-template-columns:minmax(0,1.42fr) minmax(0,1fr);gap:16px;margin-bottom:16px}
.seller-sales .sales-analytics>.sales-card{min-height:310px;padding:19px}
.seller-sales .sales-card>header h2>svg{width:17px;height:17px;color:var(--sales-teal)}
.seller-sales .sales-chart{height:224px;margin:2px 0 0}
.seller-sales .sales-chart-key{padding:5px 9px;border:1px solid #def0ed;border-radius:7px;background:#f0faf8;color:var(--sales-teal);font-size:10px;font-weight:700}
.seller-sales .sales-key-orange{border-color:#f6e7d5;background:#fff7ed;color:#bb741f}
.seller-sales .sales-chart-note{font-size:10px;color:#8794a3;line-height:1.4;margin-top:7px}
.seller-sales .sales-support{grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;align-items:stretch;margin-bottom:16px}
.seller-sales .sales-support>.sales-card{min-height:196px;padding:19px}
.seller-sales .sales-support .sales-card>header{margin-bottom:19px}
